import re

_valid_class_name_pattern = re.compile(u'^[a-zA-Z0-9_]+$')


def get_if_occurs_running_keyword_exception_or_none(
        pack):  # pylint: disable=inconsistent-return-statements, unnecessary-pass
    """
    See: ute_ue/test/test_ues/android/test_runningKeywordException.py :: test_attach_me_to_other_exception
    :param pack:
    :return:
    """
    if 'class_name' in pack and 'args' in pack:
        class_name = pack['class_name']
        args = pack['args']
        if re.match(_valid_class_name_pattern, class_name):
            return eval(class_name)(*args)  # pylint: disable=eval-used
        raise HackAttemptError("Possible hack attack by trying to eval this string: '%s'" % class_name)


def raise_if_occurs_attached_running_keyword_exception_or_none(exception):
    """
    See: ute_ue/test/test_ues/android/test_runningKeywordException.py :: test_attach_me_to_other_exception
    :param exception:
    :return:
    """
    if hasattr(exception, 'ue_manager_attached_exception_pack'):
        ue_manager_attached_exception_pack = getattr(exception, 'ue_manager_attached_exception_pack')
        raise get_if_occurs_running_keyword_exception_or_none(ue_manager_attached_exception_pack)


class HackAttemptError(Exception):
    """Raises when given exception-class name seems not safe."""
    pass


