class RunningKeywordException(UeManagerException):
    """All sub-exceptions of this exception should be thrown to robot."""

    def pack_me_on_pyro_server_side(self):
        """
        See: ute_ue/test/test_ues/android/test_runningKeywordException.py :: test_attach_me_to_other_exception
        :return:
        """
        pack = {}
        pack['class_name'] = self.__class__.__name__
        pack['args'] = self.args
        return pack

    def attach_me_to_other_exception(self, exception):
        """
        See: ute_ue/test/test_ues/android/test_runningKeywordException.py :: test_attach_me_to_other_exception
        :param exception:
        """
        exception.ue_manager_attached_exception_pack = self.pack_me_on_pyro_server_side()


