    """Can not connect to ue after many reboot"""

    def __init__(self, ue_sn, reboots):
        """

        :param ue_sn:
        :param reboots:
        """
        super(UeUnreachable, self).__init__()
        self.ue_sn = ue_sn
        self.reboots = int(reboots)

    def __str__(self):
        return "Can not connect to UE %s after %d reboots" % (self.ue_sn, self.reboots)


