class NoWelcomeMessageFromServer(CannotConnectToPyroServerException):
    """Raises when server does not write welcome message on his stdout."""

    def __init__(self, server_lines, expect_welcome_msg, ip):
        """

        :param server_lines:
        :param expect_welcome_msg:
        :param ip:
        """
        super(NoWelcomeMessageFromServer, self).__init__()
        self.server_lines = server_lines
        self.expect_welcome_msg = expect_welcome_msg
        self.ip = ip

    def __str__(self):
        args = (str(self.ip), self.expect_welcome_msg, '\n'.join(self.server_lines))
        return self._str_template() % args

    def _str_template(self):
        return "From server %s expected line '%s', but server prints only: \n%s"


class TimeoutWaitingForWelcomeMessageFromServer(NoWelcomeMessageFromServer):
    """TBC"""

    def _str_template(self):
        return "Timeout while reading from server %s expected line '%s', but server prints only: \n%s"


