class AppMobileVersionIncorrect(UeManagerException):
    """TBC"""

    @staticmethod
    def expect_version(ueman, expect_version, err_msg=''):
        """
        Expects given mobile app version
        :param ueman: somethinf with method get_mobile_app_protocol_version()
        :param expect_version:
        :param err_msg:
        :raises UeManagerMobileVersionIncorrect
        """
        version = ueman.get_mobile_app_protocol_version()
        if version < expect_version:
            msgp = "{}Too low version of mobile installed. Expected version: {}. Installed version: {}."
            raise AppMobileVersionIncorrect(msgp.format(err_msg, expect_version, version))


