class InvalidJsonActionResponse(Exception):
    def __init__(self, response, action, allowed_responses):
        super(InvalidJsonActionResponse, self).__init__()
        self.json_action = action
        self.allowed_responses = allowed_responses
        self.response = response

    def __str__(self):
        return "Invalid JSON action response from action {}. \n" \
               "Response: {}\n" \
               "Allowed responses: {}".format(self.json_action, self.response, self.allowed_responses)


